# Heat medal: gold rim, enamel face, heat number, park on the face, gloss. Same style as the site's medalSVG.
def medal(n, park, enamel, uid, ribbon=True, size="100%"):
    g=f"g{uid}"; gl=f"l{uid}"; c=f"c{uid}"; arc=f"a{uid}"
    rib = f'''<path d="M58 4 L80 40 L102 4 L118 4 L92 52 L68 52 L42 4 Z" fill="{enamel}" stroke="url(#{g})" stroke-width="2"></path><path d="M74 4 L80 16 L86 4 Z" fill="#FFFFFF" opacity=".25"></path>''' if ribbon else ''
    return f'''<svg width="{size}" viewBox="0 0 160 200" role="img" aria-label="Heat {n} medal, {park}"><defs><linearGradient id="{g}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#FFF4C2"></stop><stop offset=".3" stop-color="#E3C065"></stop><stop offset=".55" stop-color="#A07A1C"></stop><stop offset=".78" stop-color="#F3DB8C"></stop><stop offset="1" stop-color="#B8902F"></stop></linearGradient><linearGradient id="{gl}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".55"></stop><stop offset=".5" stop-color="#fff" stop-opacity="0"></stop></linearGradient><clipPath id="{c}"><circle cx="80" cy="120" r="66"></circle></clipPath><path id="{arc}" d="M 34 120 A 46 46 0 0 1 126 120" fill="none"></path></defs>{rib}<circle cx="80" cy="120" r="72" fill="url(#{g})"></circle><circle cx="80" cy="120" r="62" fill="{enamel}" stroke="#9C7A22" stroke-width="1.6"></circle><circle cx="80" cy="120" r="52" fill="none" stroke="url(#{g})" stroke-width="2"></circle><text font-family="DM Mono, monospace" font-size="9" letter-spacing="2" fill="#F3DB8C" text-anchor="middle"><textPath href="#{arc}" startOffset="50%">{park.upper()}</textPath></text><text x="80" y="118" text-anchor="middle" font-family="DM Mono, monospace" font-size="8" letter-spacing="3" fill="#F3DB8C">HEAT</text><text x="80" y="150" text-anchor="middle" font-family="Archivo, sans-serif" font-weight="900" font-stretch="125%" font-size="34" fill="url(#{g})">{n}</text><g clip-path="url(#{c})"><rect x="0" y="54" width="160" height="66" fill="url(#{gl})"></rect><ellipse cx="54" cy="86" rx="34" ry="10" fill="#fff" opacity=".22" transform="rotate(-30 54 86)"></ellipse></g></svg>'''
